// Grader helpers, judge flavour. Generated by rbx for problems with a grader.
//
// A judge test is the raw input behind a hidden header:
//
//   <input secret>
//   <declaring group>
//   <raw input>
//
// and a batch grader's output starts with a prologue the checker strips:
//
//   <output secret>          printed by before_call()
//   ...anything the contestant wrote to stdout lands here...
//   <output end secret>      printed by after_call() or verdict()
//   OK | WA | PV
//   <message>                only after WA / PV
//   <answer>
//
// The prologue is written with C stdio, but a grader or contestant may write
// through an unsynchronised std::cout, whose buffer is flushed apart from it.
// So every frame flushes std::cout before it and stdout after it. Likewise the
// hidden header is read off the file descriptor, unbuffered, so the raw input
// is left for whichever of stdin and an unsynchronised std::cin the grader
// reads it with.
#include <iostream>
#if !defined(_WIN32)
#include <cerrno>
#include <unistd.h>
#endif

namespace rbx {
namespace secrets {
inline constexpr const char *kInput = "{{INPUT_SECRET}}";
inline constexpr const char *kOutput = "{{OUTPUT_SECRET}}";
inline constexpr const char *kOutputEnd = "{{OUTPUT_END_SECRET}}";
} // namespace secrets

namespace grader {

enum class Verdict { WA, PV };

namespace detail {

// 0: nothing printed, 1: before_call() printed, 2: after_call() printed.
inline int &stage() {
  static int value = 0;
  return value;
}

// Prints `text` with nothing written before it still buffered in std::cout,
// and nothing of it left buffered in stdout.
inline void printFrame(const std::string &text) {
  std::cout.flush();
  std::fputs(text.c_str(), stdout);
  std::fflush(stdout);
}

// Reads one line of stdin without buffering past it: fgetc would pull the raw
// input into stdin's buffer too, where an unsynchronised std::cin, which reads
// the descriptor itself, never sees it.
inline std::string readHeaderLine() {
  std::string line;
#if defined(_WIN32)
  int ch;
  while ((ch = std::fgetc(stdin)) != EOF && ch != '\n') {
    line.push_back(static_cast<char>(ch));
  }
#else
  char ch;
  for (;;) {
    ssize_t got = ::read(0, &ch, 1);
    if (got < 0 && errno == EINTR) {
      continue;
    }
    if (got != 1 || ch == '\n') {
      break;
    }
    line.push_back(ch);
  }
#endif
  if (!line.empty() && line.back() == '\r') {
    line.pop_back();
  }
  return line;
}

} // namespace detail

// Ends the run with a verdict the grader reached on its own, e.g. a returned
// value that breaks the rules. Must be called before after_call().
[[noreturn]] inline void verdict(Verdict kind, const std::string &message) {
  if (detail::stage() >= 2) {
    std::fprintf(stderr, "rbx: grader verdict() called after after_call()\n");
    std::abort();
  }
  if (detail::stage() == 0) {
    detail::printFrame(std::string(secrets::kOutput) + "\n");
  }
  detail::printFrame(std::string(secrets::kOutputEnd) + "\n" +
                     (kind == Verdict::WA ? "WA" : "PV") + "\n" + message +
                     "\n");
  std::exit(0);
}

// Reads the hidden header: checks the input secret, so contestant code that
// read stdin before the grader is caught, and records the test's group for
// rbx::getGroup() and the per-group getVar arms. Leaves stdin at the raw input.
inline void start() {
  if (detail::readHeaderLine() != secrets::kInput) {
    verdict(Verdict::PV, "Possible tampering with the input");
  }
  ::rbx::detail::headerGroup() = detail::readHeaderLine();
}

// Reopened on /dev/null rather than closed: reading a closed stdin is undefined
// behaviour, while this way contestant code that reads it just sees EOF.
inline void close_input() {
  if (std::freopen("/dev/null", "r", stdin) == nullptr) {
    std::fclose(stdin);
  }
}

// Call right before handing control to the contestant's code.
inline void before_call() {
  detail::printFrame(std::string(secrets::kOutput) + "\n");
  detail::stage() = 1;
}

// Call right after the contestant's code returns, before printing the answer.
inline void after_call() {
  detail::printFrame(std::string(secrets::kOutputEnd) + "\nOK\n");
  detail::stage() = 2;
}

// The convenient way to write a grader:
//
//   rbx::grader::Grader grader;        // reads and checks the hidden header
//   ... read the input ...
//   auto r = grader.run([&] {          // closes stdin, frames the calls
//     auto r = contestant_function(...);
//     if (bad(r)) grader.wrong_answer("why");   // judge-only checks go here
//     return r;
//   });                                // prints the closing secret and OK
//   ... print the answer ...
//
// The functions above remain available for graders that need finer control.
class Grader {
public:
  Grader() { start(); }

  Grader(const Grader &) = delete;
  Grader &operator=(const Grader &) = delete;

  // Runs `calls` -- the part where contestant code runs -- and returns what it
  // returns. Verdicts must be given inside it: once it returns, the run is OK.
  template <typename F> decltype(auto) run(F &&calls) {
    close_input();
    before_call();
    if constexpr (std::is_void_v<std::invoke_result_t<F>>) {
      std::forward<F>(calls)();
      after_call();
    } else {
      auto result = std::forward<F>(calls)();
      after_call();
      return result;
    }
  }

  [[noreturn]] void wrong_answer(const std::string &message) {
    verdict(Verdict::WA, message);
  }

  [[noreturn]] void protocol_violation(const std::string &message) {
    verdict(Verdict::PV, message);
  }
};

} // namespace grader
} // namespace rbx

#ifdef _TESTLIB_H_
namespace rbx {
namespace grader {
namespace detail {

inline void consumeInputHeader() {
  if (inf.readLine() != secrets::kInput) {
    quitf(_fail, "rbx: the test input does not carry the grader header");
  }
  ::rbx::detail::headerGroup() = inf.readLine();
}

// Strips a batch grader's prologue. On the answer any problem is a judge
// failure; on the contestant's output it is their fault.
inline void consumePrologue(InStream &stream, bool isAnswer) {
  auto fail = [&](const std::string &message) {
    if (isAnswer) {
      quitf(_fail, "rbx: bad grader prologue in the answer: %s",
            message.c_str());
    }
    quitf(_wa, "Protocol violation: %s", message.c_str());
  };
  if (stream.eof() || stream.readLine() != secrets::kOutput) {
    fail("possible tampering with the output");
  }
  if (stream.eof() || stream.readLine() != secrets::kOutputEnd) {
    fail("the solution wrote to standard output or terminated the grader");
  }
  std::string status = stream.eof() ? std::string() : stream.readLine();
  if (status == "OK") {
    return;
  }
  std::string message = stream.eof() ? std::string() : stream.readLine();
  if (isAnswer) {
    quitf(_fail, "rbx: the answer was produced with grader status %s: %s",
          status.c_str(), message.c_str());
  }
  if (status == "WA") {
    quitf(_wa, "%s", message.c_str());
  }
  if (status == "PV") {
    quitf(_wa, "Protocol violation: %s", message.c_str());
  }
  quitf(_fail, "rbx: unknown grader status '%s'", status.c_str());
}

} // namespace detail
} // namespace grader

// registerTestlibCmd for a grader problem's checker: strips the hidden header
// from the input and the grader prologue from both the answer and the output,
// turning a grader WA / PV into a verdict. The rest of the checker is plain
// testlib, and rbx::getGroup() / getVar see the test's group.
inline void registerGraderChecker(int argc, char *argv[]) {
  registerTestlibCmd(argc, argv);
  grader::detail::consumeInputHeader();
  grader::detail::consumePrologue(ans, true);
  grader::detail::consumePrologue(ouf, false);
}

// registerInteraction for a grader problem's interactor: strips the hidden
// header from the input. The rest of the interactor is plain testlib.
inline void registerGraderInteraction(int argc, char *argv[]) {
  registerInteraction(argc, argv);
  grader::detail::consumeInputHeader();
}

} // namespace rbx
#endif
